function prototypeInputs(){const o={};for(const k of Object.keys(prototypeFieldLabels)){const v=String($('#proto-'+k).value??'');o[k]=v.trim()===''?null:Number(v);}o.payment_ledger_complete=$('#proto-payment-ledger').checked;return o;}
function prototypeRender(result){prototypeUI.result=result;const host=$('#prototype-metrics');host.replaceChildren();for(const m of result.metrics.slice(0,3)){const tile=element('div',undefined,'prototype-metric');append(tile,element('strong',Number(m.value.toFixed(2))+' '+m.unit),element('span',m.name));host.append(tile)}const list=$('#prototype-findings');list.replaceChildren();for(const f of result.findings){const row=element('article',undefined,'prototype-finding');append(row,element('span',f.domain.toUpperCase()+' · '+f.kind.replaceAll('_',' '),'badge'),element('h4',f.title),element('p',f.detail),element('p','Preventive option: '+f.candidate_action));list.append(row)}if(result.missing_fields.length)list.append(element('p','Insufficient data: '+result.missing_fields.join('; '),'error'));$('#prototype-ports').replaceChildren(element('p','Entity resolution FR07: not connected · As-of reconstruction FR08: not connected · Strategy/simulation FR12: not connected. Evidence and rule observations remain usable.'),element('p','Conditional arithmetic is not a policy ranking, trained agent or proven business gain.','hint'));}
async function prototypeRead(){if(!$('#prototype-start'))return;const ticket=++prototypeUI.ticket;try{const url=new URL(window.location.href);prototypeUI.caseId=prototypeUI.caseId||url.searchParams.get('case_id');const r=await request('/api/prototype'+(prototypeUI.caseId?'?case_id='+encodeURIComponent(prototypeUI.caseId):''));if(ticket!==prototypeUI.ticket||state.view!=='decisions')return;prototypeUI.fixture=r.fixture;prototypeUI.detail=r.case;const recent=r.case?.reviews.find(r=>r.kind==='prototype_analysis');const inputs=prototypeUI.draft?.caseId===prototypeUI.caseId?prototypeUI.draft.inputs:recent?.payload?.inputs||r.fixture.inputs;const fields=$('#prototype-fields');fields.replaceChildren();for(const[k,label]of Object.entries(prototypeFieldLabels)){const l=element('label',label),n=element('input');n.id='proto-'+k;n.type='number';n.min='0';n.step='any';n.value=inputs[k]??'';l.append(n);fields.append(l)}const l=element('label','Payment ledger complete for this case'),check=element('input');check.id='proto-payment-ledger';check.type='checkbox';check.checked=inputs.payment_ledger_complete;l.append(check);fields.append(l);$('#prototype-layers').replaceChildren(element('p','Fixture world/knowledge clock: '+r.fixture.world_time+' · '+r.fixture.knowledge_mode),factList(Object.entries(r.fixture.four_layers)));$('#prototype-status').textContent=prototypeUI.caseId?'Saved linked case · SYNTHETIC operating data · actual public evidence is cited separately.':'Preview only · explicit synthetic operating fixture. Open the case to save analyses, evidence and human decisions.';for(const id of ['prototype-public-evidence','prototype-save'])$('#'+id).disabled=!prototypeUI.caseId;const ev=$('#prototype-evidence');ev.replaceChildren();for(const e of r.case?.evidence||[]){const b=element('button',e.snapshot.metadata.title+' · '+e.association_status);b.addEventListener('click',async()=>{show('filter');await selectItem({version_id:e.version_id});});ev.append(b)}if(!ev.children.length)ev.append(element('p','No public evidence attached. Use the saved-record browser to attach an immutable version; a lexical match does not prove impact.','hint'));const history=$('#prototype-history');history.replaceChildren();prototypeUI.actionId=r.case?.actions[0]?.id||null;if(prototypeUI.actionId)history.append(element('p','Feedback target: '+r.case.actions[0].title+' · '+prototypeUI.actionId,'hint'));for(const a of r.case?.actions||[]){history.append(element('p','Decision recorded: '+a.title+' · '+a.created_at+' · no execution','prototype-history'));}for(const f of r.case?.reviews.filter(x=>x.kind==='prototype_feedback')||[])history.append(element('p','Feedback: '+f.payload.feedback+' · evaluation pending · no improvement claim','prototype-history'));$('#prototype-feedback-save').disabled=!prototypeUI.actionId;$('#prototype-decide').disabled=!prototypeUI.savedAnalysis;if(prototypeUI.caseId)await prototypeAnalyze(false);else prototypeRender(r.preview);}catch(e){$('#prototype-status').textContent='Could not load the case. '+e.message+' Previously loaded data is retained.';notice(e.message,true,e.rawDiagnostic);}}
async function prototypeAnalyze(save){if(!prototypeUI.caseId){notice('Open the synthetic case before analysing or saving.');return;}const ticket=++prototypeUI.ticket,inputs=prototypeInputs();prototypeUI.draft={caseId:prototypeUI.caseId,inputs};const r=await request(save?'/api/prototype/save-analysis':'/api/prototype/analyze',{case_id:prototypeUI.caseId,inputs});if(ticket!==prototypeUI.ticket)return;prototypeRender(r);if(save){prototypeUI.savedAnalysis=r.analysis_id;$('#prototype-decide').disabled=false;notice('Analysis saved with exact inputs and evidence snapshot. Strategy and reconstructed state remain pending.');}else{prototypeUI.savedAnalysis=null;$('#prototype-decide').disabled=true;}}
if($('#prototype-start')){
 $('#prototype-start').addEventListener('click',e=>busy(e.currentTarget,async()=>{const r=await request('/api/prototype/start',{fixture_id:'linked-operations-v0.2'});prototypeUI.caseId=r.case_id;if(prototypeUI.draft?.caseId===null)prototypeUI.draft.caseId=r.case_id;writeLocation();await prototypeRead();}));
 $('#prototype-form').addEventListener('input',()=>{prototypeUI.ticket++;prototypeUI.draft={caseId:prototypeUI.caseId,inputs:prototypeInputs()};prototypeUI.savedAnalysis=null;$('#prototype-decide').disabled=true;$('#prototype-status').textContent='Inputs changed. Update the observations and save this analysis before recording a decision; previous outputs remain visible.';});
 $('#prototype-form').addEventListener('submit',e=>{e.preventDefault();busy(e.submitter||$('#prototype-save'),()=>prototypeAnalyze(false));});
 $('#prototype-save').addEventListener('click',e=>busy(e.currentTarget,()=>prototypeAnalyze(true)));
 $('#prototype-public-evidence').addEventListener('click',()=>{$('#filter-query').value='MYR';$('#filter-source').value='stat_ecb_fx_daily_reference';$('#observation-grain').value='day';$('#observation-from').value='2026-10-08';$('#observation-to').value='2026-10-08';$('#reporting-country').value='';show('observation');});
 $('#prototype-decision-form').addEventListener('submit',e=>{e.preventDefault();busy($('#prototype-decide'),async()=>{const r=await request('/api/prototype/decide',{case_id:prototypeUI.caseId,analysis_id:prototypeUI.savedAnalysis,title:$('#prototype-decision-title').value,note:$('#prototype-decision-note').value});prototypeUI.actionId=r.action.id;notice('Human decision saved. No operating action was executed.');await prototypeRead();});});
 $('#prototype-feedback-form').addEventListener('submit',e=>{e.preventDefault();busy($('#prototype-feedback-save'),async()=>{await request('/api/prototype/feedback',{case_id:prototypeUI.caseId,action_id:prototypeUI.actionId,feedback:$('#prototype-feedback').value,note:$('#prototype-feedback-note').value});notice('Feedback saved; evaluation/training have not run.');await prototypeRead();});});
}
